INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1000, 'casual', '/ˈkæʒuəl/', 'adjective', '{"zh-TW":["休閒的；隨意的"],"en":["relaxed and unconcerned","not formal"]}', '{"root":{"text":"cas","meaning":"fall/chance (偶然)"},"suffix":{"text":"-ual","meaning":"relating to (相關的)"},"logic":"與偶然相關的，指不正式的、隨意的。"}', 'casual clothes / casual conversation / casual worker', '[{"en":"The dress code is casual on Fridays.","zh-TW":"週五的穿著規定是休閒服。"},{"en":"It was just a casual remark.","zh-TW":"那只是一句隨口說說。"}]', '{"adverb":"casually"}', NULL, 2, 1000, NULL),
(1001, 'catalog', '/ˈkætəlɒɡ/', 'noun', '{"zh-TW":["目錄；型錄"],"en":["a complete list of items arranged systematically"]}', '{"prefix":{"text":"cata-","meaning":"down/complete (完全)"},"root":{"text":"log","meaning":"word/list (字/列表)"},"logic":"完全列出的清單，即「目錄」。"}', 'product catalog / catalog of services', '[{"en":"Please refer to our online product catalog.","zh-TW":"請參閱我們的線上產品目錄。"},{"en":"The catalog lists over 5,000 items.","zh-TW":"目錄列出了5,000多項商品。"}]', NULL, NULL, 3, 1001, NULL),
(1002, 'catalyst', '/ˈkætəlɪst/', 'noun', '{"zh-TW":["催化劑；促進因素"],"en":["an agent that provokes or speeds significant change or action"]}', NULL, 'act as a catalyst / catalyst for change / economic catalyst', '[{"en":"The new policy acted as a catalyst for startup growth in the region.","zh-TW":"新政策充當了該地區初創企業增長的催化劑。"},{"en":"Technological innovation often serves as the catalyst for industry disruption.","zh-TW":"技術創新通常是行業顛覆的催化劑。"}]', '{"verb":"catalyze","adjective":"catalytic"}', NULL, 3, 1002, NULL),
(1003, 'catch', '/kætʃ/', 'verb', '{"zh-TW":["【主要意義-動詞】抓住；捕捉","【次要意義-動詞】理解；明白（口語）","【次要意義-動詞】接收到（訊號/廣播）","【次要意義-名詞】隱藏的問題；陷阱；代價"],"en":["[primary] to capture or take hold of something moving","[secondary - verb] to hear and understand something","[secondary - verb] to receive a signal or broadcast","[secondary - noun] a hidden drawback or problem with a seemingly good offer"]}', NULL, 'catch a meeting / catch someone doing / catch on / catch up / the catch is', '[{"en":"Did you catch what the director said about the new restructuring plan?","zh-TW":"你聽清楚主任說的新重組計劃了嗎？"},{"en":"The offer sounds great, but there must be a catch somewhere.","zh-TW":"這個提議聽起來很好，但一定有什麼隱藏的問題。"},{"en":"The new system is beginning to catch on with employees in all departments.","zh-TW":"新系統開始在所有部門的員工中流行起來。"}]', '{"noun":"catch-up, catch-all","adjective":"catching"}', 'catch 作動詞表「理解/聽清楚」（did you catch that?）；名詞 catch = 「隱藏的問題/陷阱」（there is a catch = 有隱藏條件）；catch on（流行起來）均是 TOEIC 閱讀常見陷阱。', 2, 1003, NULL),
(1004, 'categorical', '/ˌkætɪˈɡɒrɪkəl/', 'adjective', '{"zh-TW":["明確的；絕對的"],"en":["unambiguously explicit and direct"]}', NULL, 'categorical denial / categorical statement / categorical refusal', '[{"en":"She issued a categorical denial of all the allegations.","zh-TW":"她對所有指控發出了明確的否認。"},{"en":"The report makes a categorical distinction between the two phenomena.","zh-TW":"報告在兩種現象之間做出了明確的區分。"}]', '{"adverb":"categorically","noun":"category"}', NULL, 4, 1004, NULL),
(1005, 'category', '/ˈkætəɡəri/', 'noun', '{"zh-TW":["類別；種類"],"en":["a class or division of people or things"]}', '{"prefix":{"text":"cata-","meaning":"down (完全)"},"root":{"text":"gor","meaning":"speak/accuse (說/指出)"},"suffix":{"text":"-y","meaning":"noun ending (名詞字尾)"},"logic":"指出分類，即「類別」。"}', 'product category / fall into a category', '[{"en":"The products are divided into five main categories.","zh-TW":"產品分為五大類。"},{"en":"This expense falls into the travel category.","zh-TW":"此費用屬於差旅類別。"}]', '{"verb":"categorize","adjective":"categorical"}', NULL, 3, 1005, 283),
(1006, 'cater', '/ˈkeɪtər/', 'verb', '{"zh-TW":["迎合；提供餐飲服務"],"en":["to provide what is needed or required","to supply food and drink"]}', '{"root":{"text":"cater","meaning":"provide food (提供食物)"},"logic":"提供所需，即「迎合」。"}', 'cater to / cater for / catering service', '[{"en":"Our services cater to small and medium businesses.","zh-TW":"我們的服務迎合中小企業。"},{"en":"The hotel caters for corporate events.","zh-TW":"飯店承辦企業活動。"}]', '{"noun":"catering"}', NULL, 2, 1006, NULL),
(1007, 'catering', '/ˈkeɪtərɪŋ/', 'noun', '{"zh-TW":["餐飲服務；外燴"],"en":["the business of providing food for events"]}', NULL, 'catering service / event catering', '[{"en":"The hotel''s catering service handled the wedding reception.","zh-TW":"飯店的餐飲服務負責了婚禮接待。"},{"en":"We hired a catering company for the corporate dinner.","zh-TW":"我們為企業晚宴聘請了外燴公司。"}]', '{"verb":"cater","noun":"caterer"}', NULL, 3, 1007, NULL),
(1008, 'catering manager', '/ˈkeɪtərɪŋ ˈmænɪdʒər/', 'noun', '{"zh-TW":["餐飲經理"],"en":["a person who oversees food and beverage services for events"]}', NULL, 'hire a catering manager / catering manager responsibilities', '[{"en":"The catering manager ensured the food was served on time.","zh-TW":"餐飲經理確保了食物準時上桌。"},{"en":"A skilled catering manager can handle events of any size.","zh-TW":"熟練的餐飲經理可以處理任何規模的活動。"}]', NULL, NULL, 5, 1008, NULL),
(1009, 'catharsis', '/kəˈθɑːrsɪs/', 'noun', '{"zh-TW":["宣洩；淨化"],"en":["the process of releasing pent-up emotions through art or drama"]}', NULL, 'provide catharsis / emotional catharsis / theatrical catharsis', '[{"en":"Great tragedy offers catharsis by allowing audiences to experience strong emotions safely.","zh-TW":"偉大的悲劇通過讓觀眾安全地體驗強烈情感提供宣洩。"},{"en":"The director aimed for catharsis rather than mere entertainment.","zh-TW":"導演的目標是宣洩而非單純的娛樂。"}]', '{"adjective":"cathartic","adverb":"cathartically"}', NULL, 3, 1009, NULL),
(1010, 'cathedral', '/''kəˈθiːdrəl/', 'noun', '{"zh-TW":["大教堂"],"en":["the principal church of a diocese, with which the bishop is officially associated"]}', NULL, 'medieval cathedral / visit a cathedral / cathedral architecture', '[{"en":"The cathedral took over two centuries to complete.","zh-TW":"這座大教堂花了兩個多世紀才完工。"},{"en":"Tourists admired the stained glass windows inside the cathedral.","zh-TW":"遊客們欣賞大教堂內的彩色玻璃窗。"}]', NULL, NULL, 3, 1010, NULL),
(1011, 'causality', '/kɒˈzælɪti/', 'noun', '{"zh-TW":["因果關係"],"en":["the relationship between cause and effect"]}', NULL, 'establish causality / causality vs correlation / test for causality', '[{"en":"Establishing causality requires more than demonstrating correlation.","zh-TW":"建立因果關係需要的不僅僅是證明相關性。"},{"en":"Randomized controlled trials are the gold standard for testing causality.","zh-TW":"隨機對照試驗是測試因果關係的金標準。"}]', '{"adjective":"causal","adverb":"causally"}', NULL, 3, 1011, NULL),
(1012, 'cause', '/kɔːz/', 'noun', '{"zh-TW":["原因；引起"],"en":["the reason something happens","to make something happen"]}', NULL, 'root cause / cause damage', '[{"en":"We need to find the root cause.","zh-TW":"我們需要找出根本原因。"},{"en":"The storm caused major delays.","zh-TW":"暴風雨造成了嚴重的延誤。"}]', '{"noun":"cause","verb":"cause"}', NULL, 2, 1012, NULL),
(1013, 'cautious', '/ˈkɔːʃəs/', 'adjective', '{"zh-TW":["謹慎的；小心的"],"en":["careful to avoid potential problems or dangers"]}', '{"root":{"text":"caut","meaning":"be on guard (警戒)"},"suffix":{"text":"-ious","meaning":"full of (充滿)"},"logic":"充滿警戒的，即「謹慎的」。"}', 'cautious approach / cautious driver', '[{"en":"She is cautious about investing her money.","zh-TW":"她對投資很謹慎。"},{"en":"A cautious approach is recommended.","zh-TW":"建議採取謹慎的做法。"}]', '{"noun":"caution","adverb":"cautiously"}', NULL, 3, 1013, 835),
(1014, 'cease', '/siːs/', 'verb', '{"zh-TW":["停止；終止","停止"],"en":["to come or bring to an end","to come to an end; to stop"]}', '{"root":{"text":"cess","meaning":"go/yield (走/讓步)"},"logic":"讓步停下來，即「停止」。"}', 'cease operations / cease to exist; cease operations / cease to exist / cease-fire', '[{"en":"The factory will cease operations at the end of the month.","zh-TW":"工廠將在月底停止營運。"},{"en":"The company has ceased trading.","zh-TW":"公司已停止營業。"},{"en":"The factory will cease operations next month.","zh-TW":"工廠下個月將停止運營。"},{"en":"The company ceased to exist after bankruptcy.","zh-TW":"公司破產後就不復存在了。"}]', '{"noun":"cessation","adjective":"ceaseless"}', NULL, 2, 1014, NULL),
(1015, 'cease and desist', '/siːs ænd dɪˈsɪst/', 'noun', '{"zh-TW":["停止侵害令"],"en":["a legal order to stop a specific activity"]}', NULL, 'issue a cease and desist / receive a cease and desist', '[{"en":"The company sent a cease and desist letter to the imitator.","zh-TW":"公司向仿冒者發送了停止侵害通知函。"},{"en":"Ignoring a cease and desist can result in a court injunction.","zh-TW":"無視停止侵害令可能導致法院禁令。"}]', NULL, NULL, 5, 1015, NULL),
(1016, 'ceiling price', '/ˈsiːlɪŋ praɪs/', 'noun', '{"zh-TW":["價格上限"],"en":["the maximum price allowed by law or regulation for a good or service"]}', NULL, 'enforce a ceiling price / ceiling price regulation', '[{"en":"The government set a ceiling price on essential food items.","zh-TW":"政府對基本食品設定了價格上限。"},{"en":"Ceiling prices protect consumers but may lead to supply shortages.","zh-TW":"價格上限保護消費者但可能導致供應短缺。"}]', '{"opposite":"floor price"}', NULL, 5, 1016, NULL),
(1017, 'celebrate', '/ˈselɪbreɪt/', 'verb', '{"zh-TW":["慶祝"],"en":["to mark an event with festivities"]}', '{"root":{"text":"celebr","meaning":"honor (尊崇)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使其受到尊崇紀念，即「慶祝」。"}', 'celebrate a birthday / celebrate success', '[{"en":"They celebrated their anniversary with a dinner.","zh-TW":"他們以晚餐慶祝結婚紀念日。"},{"en":"The team celebrated their victory.","zh-TW":"團隊慶祝了他們的勝利。"}]', '{"noun":"celebration"}', NULL, 3, 1017, NULL),
(1018, 'celebrity', '/sɪˈlɛbrɪti/', 'noun', '{"zh-TW":["名人"],"en":["a famous person"]}', NULL, 'celebrity status / celebrity gossip', '[{"en":"Many celebrities attended the event.","zh-TW":"許多名人出席了活動。"},{"en":"She became a celebrity overnight.","zh-TW":"她一夜成名。"}]', NULL, NULL, 3, 1018, NULL),
(1019, 'cell', '/sɛl/', 'noun', '{"zh-TW":["細胞；牢房；手機"],"en":["the smallest unit of a living thing"]}', NULL, 'cell phone / prison cell', '[{"en":"Red blood cells carry oxygen.","zh-TW":"紅血球攜帶氧氣。"},{"en":"What''s your cell phone number?","zh-TW":"你的手機號碼是什麼？"}]', NULL, NULL, 1, 1019, NULL),
(1020, 'census', '/ˈsɛnsəs/', 'noun', '{"zh-TW":["人口普查"],"en":["an official count of the population"]}', NULL, 'national census / census data', '[{"en":"The census is conducted every ten years.","zh-TW":"人口普查每十年進行一次。"},{"en":"Census data shows population growth.","zh-TW":"人口普查數據顯示人口成長。"}]', NULL, NULL, 2, 1020, NULL),
(1021, 'center', '/ˈsɛntər/', 'noun', '{"zh-TW":["中心；中央"],"en":["the middle point","a building for a particular activity","the middle point of something"]}', NULL, 'shopping center / call center; city center / shopping center', '[{"en":"The call center operates 24 hours.","zh-TW":"客服中心24小時運營。"},{"en":"The city center is very busy.","zh-TW":"市中心非常繁忙。"},{"en":"The hotel is in the city center.","zh-TW":"飯店在市中心。"},{"en":"She is the center of attention.","zh-TW":"她是眾人關注的焦點。"}]', '{"noun":"center","adjective":"central","verb":"centralize","adverb":"centrally"}', NULL, 2, 1021, NULL),
(1022, 'central', 'ˈsɛntrəl', 'adjective', '{"zh-TW":["中心的；中央的","重要的"],"en":["in the middle","very important"]}', NULL, 'central location/central issue', '[{"en":"This is the central issue we need to address.","zh-TW":"這是我們需要解決的核心問題。"}]', '{"noun":"center","adverb":"centrally"}', NULL, 3, 1022, NULL),
(1023, 'central bank', '/ˈsentrəl bæŋk/', 'noun', '{"zh-TW":["中央銀行"],"en":["a national bank that manages a country monetary policy and currency"]}', NULL, 'consult the central bank / central bank policy / central bank rate', '[{"en":"The central bank raised interest rates to combat inflation.","zh-TW":"中央銀行提高利率以應對通貨膨脹。"},{"en":"Central bank decisions affect borrowing costs across the economy.","zh-TW":"中央銀行的決定影響整個經濟的借貸成本。"}]', NULL, NULL, 4, 1023, NULL),
(1024, 'central processing unit', '/ˈsentrəl ˈprəʊsesɪŋ ˈjuːnɪt/', 'noun', '{"zh-TW":["中央處理器；CPU"],"en":["the primary component of a computer that executes instructions"]}', NULL, 'CPU performance / upgrade the CPU / multi-core CPU', '[{"en":"A faster CPU reduces computation time for complex tasks.","zh-TW":"更快的CPU減少了複雜任務的計算時間。"},{"en":"Modern CPUs have multiple cores to enable parallel processing.","zh-TW":"現代CPU有多個核心以支持並行處理。"}]', NULL, NULL, 5, 1024, NULL),
(1025, 'centralization', '/ˌsentrəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["集中化；中央集權"],"en":["the process of bringing activities under a single authority"]}', NULL, 'organizational centralization / degree of centralization / centralization of data', '[{"en":"Centralization of IT infrastructure reduces costs and improves security.","zh-TW":"IT基礎設施的集中化降低了成本並提高了安全性。"},{"en":"Excessive centralization can slow down decision-making in large organizations.","zh-TW":"過度集中化可能減慢大型組織的決策速度。"}]', '{"verb":"centralize","adjective":"centralized"}', NULL, 5, 1025, NULL),
(1026, 'centralize', '/ˈsentrəlaɪz/', 'verb', '{"zh-TW":["集中化"],"en":["to bring under a single central authority"]}', '{"root":{"text":"centr","meaning":"center (中心)"},"suffix":{"text":"-alize","meaning":"to make (使)"},"logic":"使集中到中心，即「集中化」。"}', 'centralize operations/management/control', '[{"en":"The company centralized all IT operations.","zh-TW":"公司將所有IT營運集中化。"},{"en":"Centralizing procurement can reduce costs.","zh-TW":"集中採購可以降低成本。"}]', '{"noun":"centralization","adjective":"centralized"}', NULL, 4, 1026, NULL),
(1027, 'CEO', '/ˌsiː iː ˈoʊ/', 'noun', '{"zh-TW":["執行長；首席執行官"],"en":["chief executive officer; the highest-ranking executive in a company"]}', NULL, 'appoint a CEO / role of CEO / CEO succession', '[{"en":"The CEO announced a major restructuring at the annual conference.","zh-TW":"執行長在年度會議上宣布了重大重組。"},{"en":"The new CEO brought a fresh strategic vision to the company.","zh-TW":"新執行長為公司帶來了全新的戰略願景。"}]', '{"full form":"chief executive officer"}', NULL, 1, 1027, NULL),
(1028, 'ceramic', '/səˈræmɪk/', 'noun', '{"zh-TW":["陶瓷"],"en":["objects made from clay that is heated to high temperatures"]}', '{"root":{"text":"ceram","meaning":"potter''s clay (陶土)"},"suffix":{"text":"-ic","meaning":"relating to (相關的)"},"logic":"與陶土相關的，即「陶瓷」。"}', 'ceramic tile / ceramic art', '[{"en":"The floor is covered with ceramic tiles.","zh-TW":"地板鋪著瓷磚。"},{"en":"She took a ceramic art class.","zh-TW":"她上了一堂陶藝課。"}]', '{"noun":"ceramics"}', NULL, 3, 1028, NULL),
(1029, 'certain', '/ˈsɜːrtən/', 'adjective', '{"zh-TW":["確定的；某些"],"en":["sure; having no doubt","specific but not named"]}', NULL, 'for certain / certain conditions', '[{"en":"I am certain the data is correct.","zh-TW":"我確定資料是正確的。"},{"en":"Certain conditions must be met.","zh-TW":"必須滿足某些條件。"}]', '{"adjective":"certain","adverb":"certainly","noun":"certainty"}', NULL, 3, 1029, NULL),
(1030, 'certificate', '/sərˈtɪfɪkət/', 'noun', '{"zh-TW":["證書；執照","證書；證明"],"en":["an official document attesting a fact","an official document proving something"]}', '{"root":{"text":"cert","meaning":"sure (確定)"},"suffix":{"text":"-ificate","meaning":"thing made (製成品)"},"logic":"使確定的文件，即「證書」。"}', 'certificate of completion / professional certificate; birth certificate / certificate program', '[{"en":"Applicants must provide a certificate of qualification.","zh-TW":"申請者必須提供資格證書。"},{"en":"She earned a professional certificate in project management.","zh-TW":"她取得了專案管理的專業證書。"},{"en":"She received a certificate of completion.","zh-TW":"她收到了結業證書。"},{"en":"You need a birth certificate to apply.","zh-TW":"你需要出生證明才能申請。"}]', '{"verb":"certify","noun":"certification","noun2":"certification"}', NULL, 4, 1030, 79),
(1031, 'certificate of origin', '/səˈtɪfɪkɪt əv ˈɒrɪdʒɪn/', 'noun', '{"zh-TW":["原產地證書"],"en":["a document certifying the country of manufacture for exported goods"]}', NULL, 'obtain a certificate of origin / present the certificate of origin', '[{"en":"A certificate of origin is required for customs clearance in many countries.","zh-TW":"許多國家通關時需要原產地證書。"},{"en":"The certificate of origin confirmed the goods were made in Taiwan.","zh-TW":"原產地證書確認了商品在台灣製造。"}]', NULL, NULL, 5, 1031, NULL),
(1032, 'certification', '/ˌsɜːrtɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["認證；證書"],"en":["official confirmation that someone has met certain standards"]}', NULL, 'professional certification / obtain certification / certification exam', '[{"en":"PMP certification is required for senior project managers.","zh-TW":"PMP認證是高級項目經理的必要條件。"},{"en":"She passed the certification exam on her first attempt.","zh-TW":"她第一次就通過了認證考試。"}]', '{"verb":"certify","adjective":"certified","noun":"certificate"}', NULL, 5, 1032, 521),
(1033, 'certification of origin', '/ˌsɜːrtɪfɪˈkeɪʃən əv ˈɒrɪdʒɪn/', 'noun', '{"zh-TW":["原產地證明書"],"en":["a document certifying the country in which goods were produced"]}', NULL, 'issue a certificate of origin / require a certificate of origin', '[{"en":"A certificate of origin is required for preferential tariff treatment.","zh-TW":"優惠關稅待遇需要原產地證明書。"},{"en":"The exporter submitted the certificate of origin to customs.","zh-TW":"出口商向海關提交了原產地證明書。"}]', NULL, NULL, 5, 1033, NULL),
(1034, 'certified check', '/ˈsɜːrtɪfaɪd tʃek/', 'noun', '{"zh-TW":["保付支票"],"en":["a check guaranteed by the issuing bank to have sufficient funds"]}', NULL, 'issue a certified check / require a certified check', '[{"en":"The landlord required a certified check for the security deposit.","zh-TW":"房東要求用保付支票支付押金。"},{"en":"A certified check reduces the risk of a payment being dishonoured.","zh-TW":"保付支票降低了付款被拒絕的風險。"}]', '{"synonym":"guaranteed check"}', NULL, 5, 1034, NULL),
(1035, 'certified public accountant', '/ˈsɜːrtɪˌfaɪd ˈpʌblɪk əˈkaʊntənt/', 'noun', '{"zh-TW":["注冊會計師；公認會計師"],"en":["a licensed professional accountant"]}', NULL, 'hire a certified public accountant / CPA firm', '[{"en":"She hired a certified public accountant to prepare her tax return.","zh-TW":"她聘請了注冊會計師準備她的稅務申報。"},{"en":"Our accounts are audited by a certified public accountant annually.","zh-TW":"我們的帳目每年由注冊會計師審計。"}]', '{"abbreviation":"CPA"}', NULL, 5, 1035, NULL),
(1036, 'certiorari', '/ˌsɜːrʃiəˈreɪri/', 'noun', '{"zh-TW":["調卷令"],"en":["an order by a higher court to review a lower court''s decision"]}', NULL, 'grant certiorari / petition for certiorari / writ of certiorari', '[{"en":"The Supreme Court granted certiorari to hear the appeal.","zh-TW":"最高法院發出調卷令以審理上訴。"},{"en":"A writ of certiorari is the primary way to appeal to the US Supreme Court.","zh-TW":"調卷令是向美國最高法院上訴的主要方式。"}]', NULL, NULL, 4, 1036, NULL),
(1037, 'cession', '/ˈseʃən/', 'noun', '{"zh-TW":["割讓；讓渡"],"en":["the formal giving up of rights, property, or territory"]}', NULL, 'territorial cession / cession of rights / voluntary cession', '[{"en":"The cession of the territory was formalized in the peace treaty.","zh-TW":"領土割讓在和平條約中得到正式確認。"},{"en":"The cession of mineral rights generated significant revenue for the tribe.","zh-TW":"礦產權的讓渡為部落帶來了可觀的收入。"}]', '{"verb":"cede"}', NULL, 3, 1037, NULL),
(1038, 'CFO', '/ˌsiː ef ˈoʊ/', 'noun', '{"zh-TW":["財務長；首席財務官"],"en":["chief financial officer; the executive responsible for financial strategy"]}', NULL, 'CFO role / appoint a CFO / CFO responsibilities', '[{"en":"The CFO presented the annual financial results to investors.","zh-TW":"財務長向投資者呈報了年度財務業績。"},{"en":"The CFO oversees budgeting, forecasting, and financial reporting.","zh-TW":"財務長負責監督預算、預測和財務報告。"}]', '{"full form":"chief financial officer"}', NULL, 1, 1038, NULL),
(1039, 'chain', '/tʃeɪn/', 'noun', '{"zh-TW":["鏈條；連鎖"],"en":["a series of metal rings connected together"]}', NULL, 'food chain / chain reaction', '[{"en":"The dog was on a chain.","zh-TW":"狗被拴在鏈條上。"},{"en":"It''s a popular restaurant chain.","zh-TW":"這是一家受歡迎的連鎖餐廳。"}]', NULL, NULL, 2, 1039, NULL),
(1040, 'chain of command', '/tʃeɪn əv kəˈmɑːnd/', 'noun', '{"zh-TW":["指揮鏈；命令鏈"],"en":["the hierarchy of authority in an organization"]}', NULL, 'respect the chain of command / follow the chain of command', '[{"en":"All decisions must be approved through the chain of command.","zh-TW":"所有決定必須通過指揮鏈批准。"},{"en":"Issues should be escalated through the proper chain of command.","zh-TW":"問題應通過適當的指揮鏈升級處理。"}]', NULL, NULL, 5, 1040, NULL),
(1041, 'chair', '/tʃɛr/', 'noun', '{"zh-TW":["【主要意義-名詞】椅子","【次要意義-動詞】主持（會議）；擔任主席","【次要意義-名詞】主席；委員會主席職位"],"en":["[primary - noun] a separate seat for one person","[secondary - verb] to act as the chairperson of a meeting or committee","[secondary - noun] the position of chairperson"]}', NULL, 'chair a meeting / chair a committee / take the chair / address the chair', '[{"en":"She was asked to chair the quarterly review meeting.","zh-TW":"她被要求主持季度審查會議。"},{"en":"Who will chair the board meeting in the director''s absence?","zh-TW":"主任缺席時誰來主持董事會會議？"},{"en":"He has chaired the finance committee for three consecutive years.","zh-TW":"他已連續三年擔任財務委員會主席。"}]', '{"noun":"chairperson, chairman, chairwoman, chairmanship"}', '動詞 chair = 「主持會議」，名詞 chair 也可指「主席」職位，是 TOEIC 商務語境中的高頻用法，常出現在會議通知或公告類文章。', 2, 1041, NULL),
(1042, 'chairman', 'ˈtʃɛrmən', 'noun', '{"zh-TW":["主席；董事長","會長"],"en":["the head of a board","a leader of a meeting"]}', NULL, 'board chairman/chairman of the committee', '[{"en":"The chairman opened the annual meeting.","zh-TW":"主席主持了年度大會。"}]', NULL, NULL, 3, 1042, NULL),
(1043, 'chairperson', '/ˈtʃɛərˌpɜːrsən/', 'noun', '{"zh-TW":["主席；會議主持人"],"en":["the person leading a meeting or organization"]}', NULL, 'elect a chairperson / acting chairperson', '[{"en":"The chairperson opened the meeting at nine o''clock.","zh-TW":"主席在九點鐘主持開會。"},{"en":"She was elected chairperson of the board.","zh-TW":"她被選為董事會主席。"}]', '{"noun2":"chairman","noun3":"chairwoman"}', NULL, 4, 1043, NULL),
(1044, 'chalet', '/''ʃæleɪ/', 'noun', '{"zh-TW":["木屋；山間小屋"],"en":["a wooden house with a steeply sloping roof, especially in the Alps"]}', NULL, 'ski chalet / mountain chalet / cozy chalet', '[{"en":"They rented a chalet in the Alps for a week of skiing.","zh-TW":"他們在阿爾卑斯山租了一棟木屋，享受一週的滑雪。"},{"en":"The chalet had a fireplace and panoramic views of the snowy peaks.","zh-TW":"這棟山間小屋有壁爐，可以看到白雪皚皚的山峰全景。"}]', NULL, NULL, 2, 1044, NULL),
(1045, 'challenge', '/ˈtʃælɪndʒ/', 'noun', '{"zh-TW":["挑戰；難題"],"en":["a task or situation that tests abilities"]}', '{"root":{"text":"challenge","meaning":"accusation/call to fight (指控/挑戰)"},"logic":"呼叫對抗，即「挑戰」。"}', 'face a challenge / overcome challenges / major challenge', '[{"en":"The biggest challenge is meeting the tight deadline.","zh-TW":"最大的挑戰是趕上緊迫的截止日期。"},{"en":"We must overcome these challenges to succeed.","zh-TW":"我們必須克服這些挑戰才能成功。"}]', '{"adjective":"challenging"}', NULL, 3, 1045, 285),
(1046, 'challenging', 'ˈtʃælɪndʒɪŋ', 'adjective', '{"zh-TW":["挑戰性的；有難度的","艱鉅的"],"en":["difficult but stimulating","testing your abilities"]}', NULL, 'challenging task/challenging environment', '[{"en":"This is a challenging but rewarding role.","zh-TW":"這是一個具有挑戰性但有意義的職位。"}]', '{"noun":"challenge","adverb":"challengingly"}', NULL, 4, 1046, NULL),
(1047, 'chamber', '/ˈtʃeɪmbər/', 'noun', '{"zh-TW":["會議廳；商會"],"en":["a large room used for meetings","an enclosed space"]}', '{"root":{"text":"camer","meaning":"room (房間)"},"logic":"房間，即「會議廳」。"}', 'chamber of commerce / chamber music', '[{"en":"The chamber of commerce supports local businesses.","zh-TW":"商會支持當地企業。"},{"en":"The proposal was debated in the upper chamber.","zh-TW":"該提案在上議院進行辯論。"}]', NULL, NULL, 3, 1047, NULL),
(1048, 'championship', '/ˈtʃæmpiənʃɪp/', 'noun', '{"zh-TW":["錦標賽；冠軍地位"],"en":["a competition to find the best player or team"]}', NULL, 'world championship / win the championship', '[{"en":"They won the national championship.","zh-TW":"他們贏得了全國錦標賽。"},{"en":"The championship game is tomorrow.","zh-TW":"冠軍賽明天舉行。"}]', '{"noun2":"champion"}', NULL, 4, 1048, NULL),
(1049, 'chance', '/tʃæns/', 'noun', '{"zh-TW":["機會；可能性"],"en":["an opportunity","possibility of something happening","an opportunity; a possibility"]}', NULL, 'by chance / take a chance', '[{"en":"There is a good chance of promotion.","zh-TW":"有很好的升遷機會。"},{"en":"We met by chance at the airport.","zh-TW":"我們在機場巧遇。"},{"en":"Give me one more chance.","zh-TW":"再給我一次機會。"},{"en":"We met by chance at the airport.","zh-TW":"我們在機場偶然相遇。"}]', '{"noun":"chance","adjective":"chance"}', NULL, 2, 1049, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1050, 'change', '/tʃeɪndʒ/', 'verb', '{"zh-TW":["改變；變化","改變；更換"],"en":["to make or become different","to become different or make something different"]}', NULL, 'make a change / change of plan; change mind / climate change', '[{"en":"We need to change our strategy.","zh-TW":"我們需要改變策略。"},{"en":"There has been a change of plan.","zh-TW":"計畫有了變動。"},{"en":"People can change.","zh-TW":"人是可以改變的。"},{"en":"I need to change my clothes.","zh-TW":"我需要換衣服。"}]', '{"verb":"change","noun":"change","adjective":"changeable"}', NULL, 2, 1050, NULL),
(1051, 'change management', '/tʃeɪndʒ ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["變革管理"],"en":["a structured approach to transitioning organizations to a new state"]}', NULL, 'change management plan / effective change management', '[{"en":"Change management is critical during mergers.","zh-TW":"變革管理在合併期間至關重要。"},{"en":"The HR team led the change management initiative.","zh-TW":"人力資源團隊主導了變革管理計劃。"}]', '{"verb":"manage change"}', NULL, 5, 1051, NULL),
(1052, 'change request', '/tʃeɪndʒ rɪˈkwest/', 'noun', '{"zh-TW":["變更請求"],"en":["a formal proposal to modify a project''s scope, timeline, or resources"]}', NULL, 'submit a change request / approve a change request / change request form', '[{"en":"Any new requirement must be submitted as a change request.","zh-TW":"任何新需求都必須以變更請求的形式提交。"},{"en":"The client''s change request added three weeks to the schedule.","zh-TW":"客戶的變更請求在排程上增加了三週。"}]', '{"plural":"change requests"}', NULL, 5, 1052, NULL),
(1053, 'channel', '/ˈtʃænl/', 'noun', '{"zh-TW":["管道；頻道","途徑"],"en":["a medium for communication or distribution"]}', '{"root":{"text":"canal","meaning":"canal/pipe (運河/管道)"},"logic":"傳送的管道，即「頻道、途徑」。"}', 'distribution channel / sales channel / communication channel', '[{"en":"We use multiple channels to reach our customers.","zh-TW":"我們使用多種管道接觸客戶。"},{"en":"Social media has become an important marketing channel.","zh-TW":"社群媒體已成為重要的行銷管道。"}]', NULL, NULL, 3, 1053, NULL),
(1054, 'channel partner', '/ˈtʃænəl ˈpɑːrtnər/', 'noun', '{"zh-TW":["通路合作夥伴；渠道夥伴"],"en":["a third-party company that sells or supports a vendor''s products"]}', NULL, 'recruit channel partners / channel partner program / channel partner agreement', '[{"en":"Channel partners extend the company''s reach into new markets.","zh-TW":"通路合作夥伴將公司的覆蓋範圍擴展至新市場。"},{"en":"The channel partner program includes training and marketing support.","zh-TW":"通路合作夥伴計劃包括培訓和行銷支援。"}]', '{"plural":"channel partners"}', NULL, 5, 1054, NULL),
(1055, 'chapter', '/ˈtʃæptər/', 'noun', '{"zh-TW":["章節"],"en":["a main division of a book"]}', NULL, 'new chapter / chapter by chapter', '[{"en":"Read chapter three for homework.","zh-TW":"回家作業請讀第三章。"},{"en":"A new chapter of her life began.","zh-TW":"她人生的新篇章開始了。"}]', NULL, NULL, 3, 1055, NULL),
(1056, 'character', '/ˈkærɪktər/', 'noun', '{"zh-TW":["角色；性格；字元"],"en":["a person in a story; the qualities of a person"]}', NULL, 'main character / out of character', '[{"en":"Who is your favorite character?","zh-TW":"你最喜歡的角色是誰？"},{"en":"That behavior is out of character for him.","zh-TW":"那種行為不像他。"}]', '{"noun2":"characteristic"}', NULL, 3, 1056, NULL),
(1057, 'characteristic', '/ˌkærɪktəˈrɪstɪk/', 'noun', '{"zh-TW":["特徵；特性"],"en":["a feature typical of a person or thing"]}', '{"root":{"text":"character","meaning":"mark/stamp (標記)"},"suffix":{"text":"-istic","meaning":"relating to (相關的)"},"logic":"與標記相關的特點，即「特徵」。"}', 'key characteristic / distinctive characteristic', '[{"en":"Patience is one of her best characteristics.","zh-TW":"耐心是她最好的特質之一。"},{"en":"What are the characteristics of this material?","zh-TW":"這種材料的特性是什麼？"}]', '{"verb":"characterize","adverb":"characteristically"}', NULL, 5, 1057, NULL),
(1058, 'characterize', 'ˈkærɪktəraɪz', 'verb', '{"zh-TW":["描述；表徵","刻畫"],"en":["to describe the qualities of","to define characteristics"]}', NULL, 'characterize a situation/characterize trends', '[{"en":"How would you characterize the market?","zh-TW":"您如何描述這個市場？"}]', '{"noun":"characteristic","adjective":"characteristic","adverb":"characteristically"}', NULL, 4, 1058, NULL),
(1059, 'charge', '/tʃɑːrdʒ/', 'verb', '{"zh-TW":["【主要意義-動詞/名詞】充電；收費","【次要意義-名詞】指控；控罪","【次要意義-動詞】負責；掌管"],"en":["[primary] to power a battery; to ask a price","[secondary - noun] a formal accusation in law","[secondary - verb] to be responsible for; to take control of"]}', '{"root":{"text":"charge","meaning":"load (裝載)"},"logic":"裝載責任或費用，即「收費、負責」。"}', 'in charge of / free of charge / take charge / charge with / press charges', '[{"en":"Who will be in charge of the project while the manager is on leave?","zh-TW":"經理休假期間由誰負責這個專案？"},{"en":"The firm was charged with violating antitrust regulations.","zh-TW":"該公司被控違反反壟斷法規。"},{"en":"Delivery is free of charge for orders exceeding 100 dollars.","zh-TW":"訂單超過100美元即可免費送貨。"}]', '{"noun":"chargeable"}', 'charge 有三個 TOEIC 必考用法：in charge of（負責），free of charge（免費），be charged with（被指控），考生容易只記住「充電/收費」而忽略法律和管理方面的含義。', 2, 1059, 286),
(1060, 'charge account', '/tʃɑːrdʒ əˈkaʊnt/', 'noun', '{"zh-TW":["賒帳帳戶；信用帳戶"],"en":["a credit arrangement allowing purchases to be paid later"]}', NULL, 'open a charge account / charge account limit', '[{"en":"Corporate clients were offered charge account facilities for monthly billing.","zh-TW":"企業客戶獲得了按月計費的賒帳帳戶設施。"},{"en":"A charge account requires creditworthiness assessment before approval.","zh-TW":"賒帳帳戶在批准之前需要信用狀況評估。"}]', NULL, NULL, 5, 1060, NULL),
(1061, 'charge off', '/tʃɑːrdʒ ɒf/', 'verb', '{"zh-TW":["核銷；沖銷"],"en":["to remove a bad debt from accounts receivable as uncollectible"]}', NULL, 'charge off a bad debt / write-off / charge-off rate', '[{"en":"The bank charged off 10 million in non-performing loans.","zh-TW":"銀行核銷了1000萬元的不良貸款。"},{"en":"A high charge-off rate signals poor credit quality in the portfolio.","zh-TW":"高核銷率表明投資組合中的信用品質差。"}]', '{"noun":"charge-off","adjective":"charged off"}', NULL, 4, 1061, NULL),
(1062, 'charge-off', '/ˈtʃɑːrdʒ ɒf/', 'noun', '{"zh-TW":["沖銷；呆帳沖銷"],"en":["the declaration by a creditor that an amount of debt is unlikely to be collected"]}', NULL, 'record a charge-off / charge-off rate', '[{"en":"The bank increased its charge-off rate after rising loan defaults.","zh-TW":"銀行在貸款違約增加後提高了沖銷率。"},{"en":"A charge-off reduces the asset value on the creditor''s balance sheet.","zh-TW":"沖銷降低了債權人資產負債表上的資產價值。"}]', NULL, NULL, 4, 1062, NULL),
(1063, 'chart', 'tʃɑːrt', 'verb', '{"zh-TW":["繪製圖表；記錄","規劃"],"en":["to make a graph or map","to plan a course"]}', NULL, 'chart progress/chart a course', '[{"en":"Let''s chart the progress on a timeline.","zh-TW":"讓我們用時間軸記錄進度。"}]', '{"noun":"chart","adjective":"charted"}', NULL, 2, 1063, NULL),
(1064, 'charter', '/ˈtʃɑːrtər/', 'noun', '{"zh-TW":["章程；特許狀"],"en":["a written grant of rights by a government or other authority; also to hire a vehicle"]}', NULL, 'company charter / charter flight / charter a vessel', '[{"en":"The company was founded under a royal charter in 1850.","zh-TW":"公司於1850年在皇家特許狀下成立。"},{"en":"The team chartered a private jet for the urgent overseas trip.","zh-TW":"團隊為緊急海外行程包租了私人飛機。"}]', '{"verb":"charter","adjective":"chartered"}', NULL, 3, 1064, 652),
(1065, 'charter flight', '/ˈtʃɑːrtər flaɪt/', 'noun', '{"zh-TW":["包機；包機航班"],"en":["a flight that is not part of a scheduled service"]}', NULL, 'book a charter flight / charter flight service', '[{"en":"The tour company arranged a charter flight for the group.","zh-TW":"旅行社為團體安排了包機。"},{"en":"Charter flights are often used for corporate travel.","zh-TW":"包機常用於企業商務旅行。"}]', NULL, NULL, 5, 1065, NULL),
(1066, 'charter party', '/ˈtʃɑːrtər ˈpɑːrti/', 'noun', '{"zh-TW":["租船契約"],"en":["a contract between a shipowner and a charterer for hire of a ship"]}', NULL, 'sign a charter party / charter party terms', '[{"en":"The charter party specified the freight rate and port of destination.","zh-TW":"租船契約規定了運費和目的地港口。"},{"en":"Disputes under a charter party are typically resolved through maritime arbitration.","zh-TW":"租船契約下的爭議通常通過海事仲裁解決。"}]', NULL, NULL, 5, 1066, NULL),
(1067, 'chartered accountant', '/ˌtʃɑːrtərd əˈkaʊntənt/', 'noun', '{"zh-TW":["特許會計師"],"en":["a qualified accountant who holds a recognized professional accounting designation"]}', NULL, 'appoint a chartered accountant / chartered accountant report', '[{"en":"The chartered accountant prepared the statutory accounts.","zh-TW":"特許會計師編製了法定帳目。"},{"en":"A chartered accountant must comply with the standards of their professional body.","zh-TW":"特許會計師必須遵守其專業機構的標準。"}]', '{"abbreviation":"CA"}', NULL, 5, 1067, NULL),
(1068, 'chase', '/tʃeɪs/', 'verb', '{"zh-TW":["追趕；追求"],"en":["to run after someone to catch them"]}', NULL, 'chase after / wild goose chase', '[{"en":"The dog chased the cat.","zh-TW":"狗追著貓跑。"},{"en":"Stop chasing your dreams and start building them.","zh-TW":"別再追夢了，開始實現它們吧。"}]', NULL, NULL, 2, 1068, NULL),
(1069, 'chatbot', '/ˈtʃætbɒt/', 'noun', '{"zh-TW":["聊天機器人"],"en":["a computer program that simulates conversation with users"]}', NULL, 'deploy a chatbot / AI chatbot / customer service chatbot', '[{"en":"The chatbot handles 60% of customer inquiries automatically.","zh-TW":"聊天機器人自動處理60%的客戶詢問。"},{"en":"An AI chatbot was implemented to reduce call center volume.","zh-TW":"部署了AI聊天機器人以減少呼叫中心的工作量。"}]', NULL, NULL, 3, 1069, NULL),
(1070, 'cheap', '/tʃiːp/', 'adjective', '{"zh-TW":["便宜的"],"en":["low in price; not expensive","costing little money"]}', NULL, 'cheap price / cheap labor; dirt cheap / cheap shot', '[{"en":"We found a cheaper supplier.","zh-TW":"我們找到了更便宜的供應商。"},{"en":"Cheap labor attracts manufacturers.","zh-TW":"廉價勞工吸引了製造商。"},{"en":"This bag was really cheap.","zh-TW":"這個包很便宜。"},{"en":"Flying is cheaper than taking the train.","zh-TW":"搭飛機比搭火車便宜。"}]', '{"adjective":"cheap","adverb":"cheaply","verb":"cheapen"}', NULL, 2, 1070, NULL),
(1071, 'check', '/tʃɛk/', 'verb', '{"zh-TW":["【主要意義-動詞/名詞】檢查；核查","【次要意義-名詞】（美式）支票","【次要意義-名詞】制衡；阻止","【次要意義-動詞】核對；加以限制"],"en":["[primary] to examine or verify something","[secondary - noun (AmE)] a written order to a bank to pay money","[secondary - noun] a means of controlling or restraining","[secondary - verb] to restrain or stop something"]}', NULL, 'check in / check out / check against / checks and balances / rain check', '[{"en":"The system of checks and balances prevents any single department from gaining too much power.","zh-TW":"制衡制度防止任何單一部門獲得過多權力。"},{"en":"Please check your figures against the spreadsheet before submitting.","zh-TW":"提交前請對照電子表格核查您的數字。"},{"en":"Can I take a rain check on lunch? I have a meeting at noon.","zh-TW":"午餐可以改天嗎？我中午有個會議。"}]', '{"noun":"checkbox, checkup"}', 'check 有多個次要意義：checks and balances（制衡）、rain check（改期）、check against（核對）均為 TOEIC 高頻表達，美式英語中 check 也指「支票」。', 2, 1071, NULL),
(1072, 'check register', '/tʃek ˈredʒɪstər/', 'noun', '{"zh-TW":["支票登記簿"],"en":["a record of all checks issued, including date, payee, amount, and balance"]}', NULL, 'maintain a check register / reconcile the check register', '[{"en":"The bookkeeper updated the check register after every payment.","zh-TW":"簿記員在每次付款後更新了支票登記簿。"},{"en":"A check register helps detect unauthorized or duplicate payments.","zh-TW":"支票登記簿有助於發現未經授權或重複的付款。"}]', NULL, NULL, 5, 1072, NULL),
(1073, 'check-in', '/ˈtʃɛkɪn/', 'noun', '{"zh-TW":["報到；辦理登機手續"],"en":["the process of registering arrival at a hotel or airport"]}', NULL, 'online check-in / check-in counter', '[{"en":"Online check-in opens 24 hours before departure.","zh-TW":"線上報到在出發前24小時開放。"},{"en":"Please proceed to the check-in counter with your passport.","zh-TW":"請攜帶護照前往報到櫃台。"}]', '{"verb":"check in"}', NULL, 3, 1073, NULL),
(1074, 'check-in procedure', '/ˈtʃɛkɪn prəˈsiːdʒər/', 'noun', '{"zh-TW":["入住手續"],"en":["the process followed when a guest arrives at a hotel"]}', NULL, 'streamline the check-in procedure / quick check-in procedure', '[{"en":"The hotel streamlined its check-in procedure to under three minutes.","zh-TW":"飯店將入住手續精簡到三分鐘以內。"},{"en":"Guests with pre-paid reservations enjoy a faster check-in procedure.","zh-TW":"預付訂金的賓客享有更快的入住手續。"}]', NULL, NULL, 5, 1074, NULL),
(1075, 'check-out', '/ˈtʃɛkaʊt/', 'noun', '{"zh-TW":["退房；結帳"],"en":["the process of leaving a hotel and paying the bill"]}', NULL, 'check-out time / express check-out', '[{"en":"Check-out time is at noon.","zh-TW":"退房時間是中午。"},{"en":"You can use express check-out to save time.","zh-TW":"您可以使用快速退房節省時間。"}]', '{"verb":"check out"}', NULL, 3, 1075, NULL),
(1076, 'checkout', '/ˈtʃɛkaʊt/', 'noun', '{"zh-TW":["結帳台；結帳"],"en":["the process or location for paying for goods"]}', NULL, 'go to checkout / online checkout', '[{"en":"Please proceed to the checkout when you are ready.","zh-TW":"準備好後請前往結帳台。"},{"en":"The online checkout process takes less than two minutes.","zh-TW":"線上結帳流程不到兩分鐘。"}]', '{"verb":"check out"}', NULL, 3, 1076, NULL),
(1077, 'checksum', '/ˈtʃekˌsʌm/', 'noun', '{"zh-TW":["校驗和"],"en":["a value used to verify the integrity of data after transmission"]}', NULL, 'verify checksum / compute checksum / MD5 checksum', '[{"en":"The download includes a checksum to verify the file has not been corrupted.","zh-TW":"下載包含一個校驗和以驗證文件未被損壞。"},{"en":"Checksum algorithms detect errors in data transmission.","zh-TW":"校驗和算法檢測數據傳輸中的錯誤。"}]', '{"verb":"checksum"}', NULL, 3, 1077, NULL),
(1078, 'checkup', '/ˈtʃɛkʌp/', 'noun', '{"zh-TW":["健康檢查；體檢"],"en":["a routine medical examination"]}', NULL, 'annual checkup / dental checkup', '[{"en":"He goes for a full checkup every year.","zh-TW":"他每年接受一次全面體檢。"},{"en":"The checkup revealed elevated cholesterol levels.","zh-TW":"體檢發現膽固醇偏高。"}]', NULL, NULL, 3, 1078, NULL),
(1079, 'cheerful', '/ˈtʃɪrfl/', 'adjective', '{"zh-TW":["愉快的；開朗的"],"en":["happy and positive in feeling or attitude"]}', '{"root":{"text":"cheer","meaning":"face/mood (表情/心情)"},"suffix":{"text":"-ful","meaning":"full of (充滿)"},"logic":"充滿好心情的，即「愉快的」。"}', 'cheerful smile / cheerful personality', '[{"en":"She has a cheerful personality.","zh-TW":"她有開朗的個性。"},{"en":"The room was bright and cheerful.","zh-TW":"房間明亮又令人愉悅。"}]', '{"noun":"cheerfulness","adverb":"cheerfully","verb":"cheer"}', NULL, 3, 1079, NULL),
(1080, 'cheese', '/tʃiːz/', 'noun', '{"zh-TW":["起司；乳酪"],"en":["a solid food made from milk"]}', NULL, 'cream cheese / cheese cake', '[{"en":"Would you like some cheese?","zh-TW":"你要一些起司嗎？"},{"en":"Say cheese for the photo!","zh-TW":"拍照時說起司！"}]', NULL, NULL, 2, 1080, NULL),
(1081, 'chef', '/ʃɛf/', 'noun', '{"zh-TW":["廚師；主廚"],"en":["a professional cook in a restaurant or hotel"]}', NULL, 'executive chef / head chef', '[{"en":"The head chef trained in France for five years.","zh-TW":"主廚在法國受訓了五年。"},{"en":"The chef prepared a special tasting menu for the evening.","zh-TW":"主廚為當晚準備了特別試菜菜單。"}]', NULL, NULL, 1, 1081, NULL),
(1082, 'chemotherapy', '/ˌkiːməʊˈθerəpi/', 'noun', '{"zh-TW":["化學療法；化療"],"en":["the treatment of cancer using chemical substances"]}', NULL, 'undergo chemotherapy / chemotherapy side effects / chemotherapy protocol', '[{"en":"She began a six-month chemotherapy regimen after her diagnosis.","zh-TW":"確診後她開始了六個月的化療療程。"},{"en":"Advances in chemotherapy have improved survival rates for many cancers.","zh-TW":"化療的進步提高了許多癌症的生存率。"}]', '{"adjective":"chemotherapeutic"}', NULL, 4, 1082, NULL),
(1083, 'chest', '/tʃɛst/', 'noun', '{"zh-TW":["胸部；箱子"],"en":["the front part of the body between neck and stomach"]}', NULL, 'chest pain / treasure chest', '[{"en":"He felt a pain in his chest.","zh-TW":"他感到胸口疼痛。"},{"en":"They found a treasure chest.","zh-TW":"他們找到了一個寶箱。"}]', NULL, NULL, 2, 1083, NULL),
(1084, 'chicken', '/ˈtʃɪkɪn/', 'noun', '{"zh-TW":["雞；雞肉"],"en":["a common farm bird; its meat used as food"]}', NULL, 'fried chicken / chicken out', '[{"en":"I''ll have the grilled chicken.","zh-TW":"我要烤雞。"},{"en":"Don''t chicken out now!","zh-TW":"現在別退縮！"}]', NULL, NULL, 3, 1084, NULL),
(1085, 'chief', '/tʃiːf/', 'adjective', '{"zh-TW":["主要的；首要的","首長"],"en":["most important","the leader of a group"]}', '{"root":{"text":"chief","meaning":"head (頭)"},"logic":"頭部的，即「主要的」。"}', 'chief executive / chief concern / chief officer', '[{"en":"The chief executive addressed the shareholders.","zh-TW":"執行長向股東們致辭。"},{"en":"Cost reduction is our chief concern right now.","zh-TW":"降低成本是我們目前的首要關注。"}]', '{"adverb":"chiefly"}', NULL, 2, 1085, NULL),
(1086, 'chief compliance officer', '/tʃiːf kəmˈplaɪəns ˈɒfɪsər/', 'noun', '{"zh-TW":["首席合規官"],"en":["the senior executive responsible for managing regulatory compliance"]}', NULL, 'appoint a chief compliance officer / report to chief compliance officer', '[{"en":"The chief compliance officer implemented a company-wide ethics training program.","zh-TW":"首席合規官實施了全公司道德培訓計劃。"},{"en":"Regulators require a chief compliance officer for financial institutions.","zh-TW":"監管機構要求金融機構設立首席合規官。"}]', '{"abbreviation":"CCO"}', NULL, 5, 1086, NULL),
(1087, 'chief executive officer', '/tʃiːf ɪɡˈzekjʊtɪv ˈɒfɪsər/', 'noun', '{"zh-TW":["執行長；首席執行官"],"en":["the most senior executive responsible for managing a company"]}', NULL, 'report to the CEO / appointed as CEO', '[{"en":"The new CEO outlined a bold transformation strategy.","zh-TW":"新任執行長概述了大膽的轉型策略。"},{"en":"The chief executive officer reported quarterly results to the board.","zh-TW":"執行長向董事會報告了季度業績。"}]', '{"abbreviation":"CEO"}', NULL, 5, 1087, NULL),
(1088, 'chief financial officer', '/tʃiːf faɪˈnænʃəl ˈɒfɪsər/', 'noun', '{"zh-TW":["財務長；首席財務官"],"en":["the senior executive responsible for managing a company financial affairs"]}', NULL, 'report to the CFO / become CFO / CFO responsibilities', '[{"en":"The CFO presented the annual results to the board.","zh-TW":"財務長向董事會報告了年度業績。"},{"en":"She was promoted to chief financial officer after 10 years with the firm.","zh-TW":"她在公司工作10年後晉升為財務長。"}]', '{"abbreviation":"CFO"}', NULL, 5, 1088, NULL),
(1089, 'chief operating officer', '/tʃiːf ˈɒpəreɪtɪŋ ˈɒfɪsər/', 'noun', '{"zh-TW":["首席運營官；營運長"],"en":["a senior executive responsible for day-to-day operational management"]}', NULL, 'appointed as COO / report to COO', '[{"en":"The chief operating officer managed all production and logistics.","zh-TW":"首席運營官管理所有生產和物流。"},{"en":"The COO implemented the new operational efficiency program.","zh-TW":"首席運營官實施了新的運營效率計劃。"}]', '{"abbreviation":"COO"}', NULL, 5, 1089, NULL),
(1090, 'chip', '/tʃɪp/', 'noun', '{"zh-TW":["晶片；薯片"],"en":["a tiny piece of silicon with electronic circuits"]}', NULL, 'computer chip / chip shortage', '[{"en":"The new chip is much faster.","zh-TW":"新晶片快得多。"},{"en":"There''s a global chip shortage.","zh-TW":"全球有晶片短缺的問題。"}]', NULL, NULL, 1, 1090, NULL),
(1091, 'choice', 'tʃɔɪs', 'noun', '{"zh-TW":["選擇；選項","品質"],"en":["the act of choosing","something chosen"]}', NULL, 'make a choice/wide choice', '[{"en":"You have a choice of three packages.","zh-TW":"您可以選擇三個套餐之一。"}]', '{"verb":"choose","adjective":"choosy"}', NULL, 2, 1091, NULL),
(1092, 'choir', '/kwaɪər/', 'noun', '{"zh-TW":["合唱團"],"en":["a group of people who sing together"]}', '{"root":{"text":"choir","meaning":"chorus (合唱)"},"logic":"源自拉丁語 chorus（合唱），指一群人一起歌唱。"}', 'church choir / join the choir', '[{"en":"She sings in the school choir.","zh-TW":"她在學校合唱團唱歌。"},{"en":"The choir performed at the concert hall.","zh-TW":"合唱團在音樂廳演出。"}]', NULL, NULL, 2, 1092, NULL),
(1093, 'choose', '/tʃuːz/', 'verb', '{"zh-TW":["選擇"],"en":["to pick from a number of options","to pick one from several options"]}', NULL, 'choose between / choose wisely', '[{"en":"You can choose any color you like.","zh-TW":"你可以選擇任何你喜歡的顏色。"},{"en":"They chose her as team leader.","zh-TW":"他們選她當組長。"},{"en":"You can choose any color.","zh-TW":"你可以選擇任何顏色。"},{"en":"Choose your words carefully.","zh-TW":"謹慎選擇你的用詞。"}]', '{"verb":"choose","noun":"choice","adjective":"chosen"}', NULL, 2, 1093, NULL),
(1094, 'chop', '/''tʃɒp/', 'verb', '{"zh-TW":["切碎；剁"],"en":["to cut into smaller pieces with a sharp tool"]}', NULL, 'chop finely / chop the onion / roughly chop', '[{"en":"Chop the vegetables into small cubes before adding them to the soup.","zh-TW":"在將蔬菜加入湯之前，將其切成小塊。"},{"en":"She finely chopped the garlic and added it to the hot pan.","zh-TW":"她將大蒜切碎，加入熱鍋中。"}]', '{"noun":"chop"}', NULL, 1, 1094, NULL),
(1095, 'choreography', '/ˌkɒriˈɒɡrəfi/', 'noun', '{"zh-TW":["舞蹈編排；編舞"],"en":["the sequence of steps and movements in dance or skating"]}', NULL, 'create choreography / intricate choreography / ballet choreography', '[{"en":"The choreography for the dance production took six months to perfect.","zh-TW":"這部舞蹈作品的編舞花了六個月時間完善。"},{"en":"Innovative choreography transformed the company''s artistic identity.","zh-TW":"創新的編舞改變了該公司的藝術身份。"}]', '{"verb":"choreograph","noun2":"choreographer"}', NULL, 4, 1095, NULL),
(1096, 'chronic', '/ˈkrɒnɪk/', 'adjective', '{"zh-TW":["慢性的；長期性的"],"en":["persisting for a long time or constantly recurring"]}', NULL, 'chronic pain / chronic illness / chronic condition', '[{"en":"Diabetes is a chronic condition requiring lifelong management.","zh-TW":"糖尿病是需要終身管理的慢性病。"},{"en":"Chronic stress can contribute to cardiovascular and mental health problems.","zh-TW":"慢性壓力可能導致心血管和心理健康問題。"}]', '{"adverb":"chronically","noun":"chronicity"}', NULL, 3, 1096, NULL),
(1097, 'chronic disease', '/ˈkrɒnɪk dɪˈziːz/', 'noun', '{"zh-TW":["慢性疾病"],"en":["a long-term health condition that persists or recurs"]}', NULL, 'manage a chronic disease / chronic disease prevention', '[{"en":"Diabetes is one of the most common chronic diseases.","zh-TW":"糖尿病是最常見的慢性疾病之一。"},{"en":"Lifestyle changes can help manage many chronic diseases.","zh-TW":"生活方式的改變有助於控制許多慢性疾病。"}]', '{"adjective":"chronic"}', NULL, 5, 1097, NULL),
(1098, 'chronic stress', '/''krɒnɪk stres/', 'noun', '{"zh-TW":["慢性壓力；長期壓力"],"en":["ongoing stress that persists over a long period of time, often resulting in health problems"]}', NULL, 'experience chronic stress / chronic stress management / effect of chronic stress', '[{"en":"Chronic stress has been linked to serious health conditions such as heart disease.","zh-TW":"慢性壓力與心臟病等嚴重健康狀況有關。"},{"en":"She sought therapy to learn how to manage chronic stress caused by her demanding job.","zh-TW":"她尋求心理治療，學習如何管理由高要求工作引起的慢性壓力。"}]', '{"adjective":"chronic","adjective2":"stressed"}', NULL, 5, 1098, NULL),
(1099, 'church', '/tʃɜːrtʃ/', 'noun', '{"zh-TW":["教堂"],"en":["a building for Christian worship"]}', NULL, 'go to church / church service', '[{"en":"They go to church every Sunday.","zh-TW":"他們每個星期天去教堂。"},{"en":"The church was built in 1800.","zh-TW":"這座教堂建於1800年。"}]', NULL, NULL, 2, 1099, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1100, 'churn rate', '/tʃɜːrn reɪt/', 'noun', '{"zh-TW":["客戶流失率"],"en":["the percentage of customers who stop using a service in a given period"]}', NULL, 'reduce churn rate / high churn rate / calculate churn rate', '[{"en":"A high churn rate signals dissatisfied customers.","zh-TW":"高客戶流失率表明客戶不滿意。"},{"en":"The company reduced churn rate by improving its support team.","zh-TW":"公司通過改善支援團隊降低了客戶流失率。"}]', '{"verb":"churn"}', NULL, 4, 1100, NULL),
(1101, 'cinematography', '/ˌsɪnəməˈtɒɡrəfi/', 'noun', '{"zh-TW":["電影攝影術；攝影技術"],"en":["the art of filming scenes for a film"]}', NULL, 'stunning cinematography / innovative cinematography / award-winning cinematography', '[{"en":"The film won an Oscar for its breathtaking cinematography.","zh-TW":"這部電影憑藉其令人嘆為觀止的攝影術贏得了奧斯卡獎。"},{"en":"The cinematography uses natural light to create an intimate atmosphere.","zh-TW":"這部電影的攝影術使用自然光來創造親密的氛圍。"}]', '{"noun2":"cinematographer","adjective":"cinematographic"}', NULL, 5, 1101, NULL),
(1102, 'cinnamon', '/''sɪnəmən/', 'noun', '{"zh-TW":["肉桂"],"en":["a spice made from the bark of a tropical tree, used in cooking and baking"]}', NULL, 'ground cinnamon / cinnamon stick / sprinkle with cinnamon', '[{"en":"She added ground cinnamon to the apple pie for extra warmth and flavor.","zh-TW":"她在蘋果派中加入了磨碎的肉桂，增添了溫暖的風味。"},{"en":"A cinnamon stick steeped in hot tea makes a soothing winter drink.","zh-TW":"熱茶中放入肉桂棒，製成令人舒緩的冬季飲料。"}]', NULL, NULL, 3, 1102, NULL),
(1103, 'cinéma vérité', '/ˌsɪneɪmɑː vəˈrɪteɪ/', 'noun', '{"zh-TW":["直接電影；真實電影"],"en":["a style of documentary filmmaking using handheld cameras and natural lighting"]}', NULL, 'cinéma vérité style / cinéma vérité documentary / cinéma vérité technique', '[{"en":"The director used cinéma vérité techniques to create an intimate portrait.","zh-TW":"導演使用直接電影技術創作了一幅親密的肖像。"},{"en":"Cinéma vérité aims to capture reality without staging or artifice.","zh-TW":"直接電影旨在不加排演或人工修飾地捕捉現實。"}]', NULL, NULL, 5, 1103, NULL),
(1104, 'circle', '/ˈsɜːrkəl/', 'noun', '{"zh-TW":["圓；圈子"],"en":["a round shape; a group of people"]}', NULL, 'full circle / inner circle', '[{"en":"Draw a circle on the paper.","zh-TW":"在紙上畫一個圓。"},{"en":"She has a wide circle of friends.","zh-TW":"她交友廣泛。"}]', '{"adjective":"circular"}', NULL, 2, 1104, NULL),
(1105, 'circuit', '/ˈsɜːrkɪt/', 'noun', '{"zh-TW":["電路；巡迴"],"en":["a roughly circular path or journey","an established route for events"]}', '{"root":{"text":"circ","meaning":"circle (圓)"},"suffix":{"text":"-uit","meaning":"going (去)"},"logic":"繞圈走，即「巡迴、電路」。"}', 'circuit board / short circuit / conference circuit', '[{"en":"A short circuit caused the power outage.","zh-TW":"短路導致了停電。"},{"en":"She''s well known on the conference circuit.","zh-TW":"她在會議巡迴圈中頗有名氣。"}]', NULL, NULL, 3, 1105, NULL),
(1106, 'circular', '/ˈsɜːrkjələr/', 'noun', '{"zh-TW":["通知；通函"],"en":["an official communication sent to a large number of people"]}', NULL, 'company circular / internal circular / issue a circular', '[{"en":"A circular was sent to all staff regarding the new dress code.","zh-TW":"向所有員工發送了關於新著裝規定的通知。"},{"en":"The board issued a circular announcing the CEO change.","zh-TW":"董事會發出了宣布執行長更替的通函。"}]', '{"adjective":"circular"}', NULL, 3, 1106, NULL),
(1107, 'circular economy', '/ˈsɜːrkjʊlər ɪˈkɒnəmi/', 'noun', '{"zh-TW":["循環經濟"],"en":["an economic system aimed at eliminating waste through reuse"]}', NULL, 'adopt a circular economy / circular economy model', '[{"en":"A circular economy reduces waste by reusing materials.","zh-TW":"循環經濟透過再利用材料來減少浪費。"},{"en":"The company shifted to a circular economy approach.","zh-TW":"公司轉向了循環經濟方式。"}]', NULL, NULL, 5, 1107, NULL),
(1108, 'circulate', '/ˈsɜːrkjʊleɪt/', 'verb', '{"zh-TW":["流通；散布"],"en":["to move continuously through a system","to pass from place to place"]}', '{"root":{"text":"circ","meaning":"circle (圓)"},"suffix":{"text":"-ulate","meaning":"to make (使)"},"logic":"使繞圈流動，即「流通」。"}', 'circulate a memo/report/document', '[{"en":"Please circulate the meeting minutes to all team members.","zh-TW":"請將會議記錄發送給所有團隊成員。"},{"en":"Rumors began to circulate about the merger.","zh-TW":"有關合併的傳言開始流傳。"}]', '{"noun":"circulation"}', NULL, 3, 1108, NULL),
(1109, 'circulate a document', '/ˈsɜːrkjʊleɪt ə ˈdɒkjʊmənt/', 'verb', '{"zh-TW":["傳閱文件"],"en":["to distribute a document to all relevant people"]}', NULL, 'circulate for comment / circulate before the meeting', '[{"en":"The draft policy was circulated for comment before finalization.","zh-TW":"政策草案在定案前傳閱徵求意見。"},{"en":"The agenda was circulated to all attendees a week before the meeting.","zh-TW":"議程在會議前一週傳閱給所有與會者。"}]', NULL, NULL, 5, 1109, NULL),
(1110, 'circulation', '/ˌsɜːrkjʊˈleɪʃən/', 'noun', '{"zh-TW":["發行量；流通"],"en":["the number of copies of a publication distributed"]}', NULL, 'wide circulation / circulation figure', '[{"en":"The report was sent for wide circulation among stakeholders.","zh-TW":"報告已廣泛發送給利害關係人。"},{"en":"The newsletter has a monthly circulation of 10,000 subscribers.","zh-TW":"電子報每月有10,000名訂閱者。"}]', '{"verb":"circulate","adjective":"circulated"}', NULL, 4, 1110, 759),
(1111, 'circumscribe', '/ˈsɜːrkəmskraɪb/', 'verb', '{"zh-TW":["限制；劃定界限"],"en":["to restrict something within limits; to draw a line around"]}', NULL, 'circumscribe authority / circumscribe the scope / circumscribed power', '[{"en":"The new regulation circumscribes the bank''s lending activities.","zh-TW":"新法規限制了銀行的貸款活動。"},{"en":"The constitution circumscribes the power of the executive branch.","zh-TW":"憲法劃定了行政部門的權力界限。"}]', '{"noun":"circumscription","adjective":"circumscribed"}', NULL, 4, 1111, NULL),
(1112, 'circumspect', '/''sɜːrkəmˌspekt/', 'adjective', '{"zh-TW":["謹慎的；小心翼翼的"],"en":["wary and unwilling to take risks; thinking carefully before doing something"]}', NULL, 'circumspect approach / be circumspect / circumspect decision-making', '[{"en":"A circumspect investor carefully evaluates all risks before committing funds.","zh-TW":"謹慎的投資者在投入資金前仔細評估所有風險。"},{"en":"She was circumspect about making promises she might not be able to keep.","zh-TW":"她對做出可能無法兌現的承諾持謹慎態度。"}]', '{"adverb":"circumspectly","noun":"circumspection"}', NULL, 4, 1112, NULL),
(1113, 'circumstance', '/ˈsɜːrkəmstæns/', 'noun', '{"zh-TW":["情況；環境"],"en":["a fact or condition connected with an event","a condition or fact connected with an event"]}', '{"prefix":{"text":"circum-","meaning":"around (周圍)"},"root":{"text":"stance","meaning":"stand (站立)"},"logic":"站在周圍的事物，即「情況」。"}', 'under the circumstances / in certain circumstances; under the circumstances / financial circumstances', '[{"en":"Under the circumstances, we had no choice but to cancel.","zh-TW":"在這種情況下，我們別無選擇只能取消。"},{"en":"Economic circumstances forced a change in strategy.","zh-TW":"經濟情況迫使策略改變。"},{"en":"Under the circumstances, we had no choice.","zh-TW":"在那種情況下，我們別無選擇。"},{"en":"Their financial circumstances have improved.","zh-TW":"他們的經濟狀況有所改善。"}]', '{"adjective":"circumstantial"}', NULL, 4, 1113, 80),
(1114, 'circumvent', '/''sɜːrkəmˌvent/', 'verb', '{"zh-TW":["規避；繞過"],"en":["to find a way around an obstacle, rule, or problem"]}', NULL, 'circumvent restrictions / circumvent regulations / circumvent a problem', '[{"en":"The hacker found a way to circumvent the company''s security measures.","zh-TW":"黑客找到了一種繞過公司安全措施的方法。"},{"en":"Some companies try to circumvent environmental regulations by relocating operations.","zh-TW":"一些公司試圖通過轉移業務來規避環境法規。"}]', '{"noun":"circumvention","adjective":"circumventive"}', NULL, 4, 1114, NULL),
(1115, 'citation', '/saɪˈteɪʃən/', 'noun', '{"zh-TW":["引用；引文；嘉獎"],"en":["a quotation from a published source; an official summons; an award for achievement"]}', NULL, 'academic citation / citation count / legal citation', '[{"en":"High citation counts indicate a research paper has significantly influenced its field.","zh-TW":"高引用次數表明一篇研究論文對其領域有重大影響。"},{"en":"The officer was given a citation for outstanding service to the community.","zh-TW":"這位官員因對社區的傑出服務而獲得嘉獎。"}]', '{"verb":"cite"}', NULL, 3, 1115, NULL),
(1116, 'cite', '/saɪt/', 'verb', '{"zh-TW":["引用；舉例"],"en":["to quote as evidence or an example"]}', '{"root":{"text":"cit","meaning":"call/summon (召喚)"},"logic":"召喚證據，即「引用」。"}', 'cite a source/example/reason', '[{"en":"The report cites several studies as evidence.","zh-TW":"報告引用了多項研究作為證據。"},{"en":"She cited budget constraints as the main reason.","zh-TW":"她以預算限制作為主要原因。"}]', '{"noun":"citation"}', NULL, 1, 1116, 653),
(1117, 'citizen', '/ˈsɪtɪzən/', 'noun', '{"zh-TW":["公民；市民"],"en":["a person who belongs to a country"]}', NULL, 'senior citizen / citizen rights', '[{"en":"She became a citizen last year.","zh-TW":"她去年成為了公民。"},{"en":"Every citizen has the right to vote.","zh-TW":"每位公民都有投票權。"}]', '{"noun2":"citizenship"}', NULL, 3, 1117, NULL),
(1118, 'city', '/ˈsɪti/', 'noun', '{"zh-TW":["城市"],"en":["a large town"]}', NULL, 'city center / city council', '[{"en":"The company is based in the city.","zh-TW":"公司設在城市裡。"},{"en":"The city council approved the project.","zh-TW":"市議會批准了這個專案。"}]', '{"noun":"city","adjective":"civic"}', NULL, 1, 1118, NULL),
(1119, 'city centre', '/ˈsɪti ˈsentər/', 'noun', '{"zh-TW":["市中心；城市核心區"],"en":["the central commercial and business district of a city"]}', NULL, 'located in the city centre / city centre office', '[{"en":"The new office is located in the city centre for client accessibility.","zh-TW":"新辦公室位於市中心，方便客戶到訪。"},{"en":"City centre retail rents are significantly higher than suburban locations.","zh-TW":"市中心零售租金顯著高於郊區地點。"}]', NULL, NULL, 4, 1119, NULL),
(1120, 'civil law', '/ˈsɪvɪl lɔː/', 'noun', '{"zh-TW":["民法"],"en":["the body of law relating to private disputes between individuals"]}', NULL, 'governed by civil law / civil law system', '[{"en":"The dispute was handled under civil law.","zh-TW":"該爭議依民法處理。"},{"en":"Civil law covers contracts, property, and family matters.","zh-TW":"民法涵蓋合約、財產和家庭事務。"}]', NULL, NULL, 3, 1120, NULL),
(1121, 'civil liberties', '/ˈsɪvɪl ˈlɪbərtiz/', 'noun', '{"zh-TW":["公民自由"],"en":["fundamental rights protected against government interference"]}', NULL, 'protect civil liberties / civil liberties concerns / challenge to civil liberties', '[{"en":"Freedom of speech and privacy are core civil liberties in democratic societies.","zh-TW":"言論自由和隱私是民主社會的核心公民自由。"},{"en":"Surveillance technologies raise important civil liberties questions.","zh-TW":"監控技術引發了重要的公民自由問題。"}]', NULL, NULL, 5, 1121, NULL),
(1122, 'civil rights', '/ˈsɪvɪl raɪts/', 'noun', '{"zh-TW":["公民權利"],"en":["the rights of citizens to political and social freedom and equality"]}', NULL, 'protect civil rights / civil rights movement / fight for civil rights', '[{"en":"The civil rights movement transformed American society and law.","zh-TW":"公民權利運動改變了美國社會和法律。"},{"en":"Civil rights include the right to vote, freedom of speech, and equal protection.","zh-TW":"公民權利包括投票權、言論自由和平等保護。"}]', '{"adjective":"civil-rights"}', NULL, 4, 1122, NULL),
(1123, 'civil society', '/ˈsɪvɪl səˈsaɪəti/', 'noun', '{"zh-TW":["公民社會"],"en":["the arena of voluntary associations and citizens'' groups outside the state and market"]}', NULL, 'strengthen civil society / civil society organizations / engage civil society', '[{"en":"Civil society organizations play a vital role in holding governments accountable.","zh-TW":"公民社會組織在追究政府責任方面發揮著至關重要的作用。"},{"en":"A vibrant civil society is essential for democratic governance.","zh-TW":"充滿活力的公民社會對民主治理至關重要。"}]', NULL, NULL, 5, 1123, NULL),
(1124, 'claim', '/kleɪm/', 'verb', '{"zh-TW":["聲稱；索賠"],"en":["to state something as fact","to request something as one''s right","to say something is true; to ask for money"]}', '{"root":{"text":"claim","meaning":"cry out (喊出)"},"logic":"大聲喊出主張，即「聲稱」。"}', 'claim responsibility / insurance claim / claim that; claim that / insurance claim', '[{"en":"The company claims its product is the most efficient.","zh-TW":"公司聲稱其產品最有效率。"},{"en":"She filed an insurance claim for the damaged goods.","zh-TW":"她為受損商品提出了保險索賠。"},{"en":"He claims to be an expert.","zh-TW":"他聲稱自己是專家。"},{"en":"She filed an insurance claim.","zh-TW":"她提出了保險索賠。"}]', '{"noun":"claimant"}', NULL, 2, 1124, NULL),
(1125, 'claim settlement', '/kleɪm ˈsetəlmənt/', 'noun', '{"zh-TW":["索賠解決；理賠結案"],"en":["the resolution of an insurance or legal claim through payment or agreement"]}', NULL, 'process claim settlement / claim settlement timeline', '[{"en":"The insurance company completed claim settlement within 30 days.","zh-TW":"保險公司在30天內完成了理賠結案。"},{"en":"Claim settlement negotiations reduced the payout by 20%.","zh-TW":"索賠解決談判將賠付金額減少了20%。"}]', NULL, NULL, 5, 1125, NULL),
(1126, 'claimant', '/ˈkleɪmənt/', 'noun', '{"zh-TW":["原告；索賠人"],"en":["a person making a claim, especially in a lawsuit"]}', NULL, 'successful claimant / claimant''s case / multiple claimants', '[{"en":"The claimant sought damages for personal injury.","zh-TW":"原告尋求人身傷害賠償。"},{"en":"Both claimants submitted evidence to support their respective cases.","zh-TW":"兩名原告都提交了支持各自案件的證據。"}]', '{"noun2":"claim","verb":"claim"}', NULL, 3, 1126, NULL),
(1127, 'claims processing', '/kleɪmz ˈproʊsesɪŋ/', 'noun', '{"zh-TW":["索賠處理"],"en":["reviewing and settling insurance or warranty claims"]}', NULL, 'streamline claims processing / claims processing time', '[{"en":"Digital tools reduced claims processing time from 10 days to 3 days.","zh-TW":"數位工具將索賠處理時間從10天縮短到了3天。"},{"en":"Efficient claims processing improves customer satisfaction significantly.","zh-TW":"高效的索賠處理顯著改善了客戶滿意度。"}]', NULL, NULL, 5, 1127, NULL),
(1128, 'clarification', 'ˌklærɪfɪˈkeɪʃən', 'noun', '{"zh-TW":["澄清；說明","闡明"],"en":["the act of making something clear","an explanation"]}', NULL, 'request clarification/seek clarification', '[{"en":"Please provide clarification on this point.","zh-TW":"請就此點提供澄清。"}]', '{"verb":"clarify","adjective":"clarified"}', NULL, 5, 1128, 522),
(1129, 'clarify', '/ˈklærɪfaɪ/', 'verb', '{"zh-TW":["澄清；闡明"],"en":["to make something less confusing and more clear"]}', '{"root":{"text":"clar","meaning":"clear (清楚)"},"suffix":{"text":"-ify","meaning":"to make (使)"},"logic":"使清楚，即「澄清」。"}', 'clarify a point/issue/position', '[{"en":"Could you clarify what you mean by that statement?","zh-TW":"你能澄清那句話的意思嗎？"},{"en":"The spokesperson clarified the company''s position.","zh-TW":"發言人澄清了公司的立場。"}]', '{"noun":"clarification"}', NULL, 3, 1129, 287),
(1130, 'clarity', '/''klærɪti/', 'noun', '{"zh-TW":["清晰；明確"],"en":["the quality of being coherent and intelligible; the quality of being easy to understand"]}', NULL, 'seek clarity / communicate with clarity / clarity of expression', '[{"en":"Written communication should always aim for maximum clarity.","zh-TW":"書面溝通應始終以最大程度的清晰度為目標。"},{"en":"She asked for clarity on the new guidelines before implementing them.","zh-TW":"她在執行新指南之前要求對其進行澄清。"}]', '{"adjective":"clear","adverb":"clearly"}', NULL, 3, 1130, NULL),
(1131, 'class', '/klæs/', 'noun', '{"zh-TW":["班級；課程；階級"],"en":["a group of students; a lesson"]}', NULL, 'class room / first class', '[{"en":"I have English class at 10.","zh-TW":"我10點有英文課。"},{"en":"She graduated top of her class.","zh-TW":"她以班上第一名的成績畢業。"}]', '{"adjective":"classic","noun2":"classroom"}', NULL, 2, 1131, NULL),
(1132, 'class action', '/klæs ˈækʃən/', 'noun', '{"zh-TW":["集體訴訟"],"en":["a lawsuit filed by a group of people against the same defendant"]}', NULL, 'file a class action / defend a class action', '[{"en":"A class action was launched against the company for misleading advertising.","zh-TW":"針對公司誤導性廣告的集體訴訟被提起了。"},{"en":"The class action settlement cost the company 50 million.","zh-TW":"集體訴訟和解使公司付出了5000萬元的代價。"}]', NULL, NULL, 4, 1132, NULL),
(1133, 'class participation', '/''klɑːs pɑːrˌtɪsɪˌpeɪʃən/', 'noun', '{"zh-TW":["課堂參與；課堂討論"],"en":["the act of actively engaging in a class by answering questions, contributing to discussions, and sharing ideas"]}', NULL, 'encourage class participation / graded on class participation / improve class participation', '[{"en":"Class participation often makes up a significant portion of the course grade.","zh-TW":"課堂參與通常佔課程成績的很大一部分。"},{"en":"She was initially shy but gradually increased her class participation throughout the semester.","zh-TW":"她起初很害羞，但在整個學期中逐漸增加了課堂參與。"}]', '{"verb":"participate"}', NULL, 5, 1133, NULL),
(1134, 'classic', '/ˈklæsɪk/', 'adjective', '{"zh-TW":["經典的"],"en":["judged over time to be of the highest quality"]}', '{"root":{"text":"class","meaning":"class/rank (等級)"},"suffix":{"text":"-ic","meaning":"relating to (相關的)"},"logic":"屬於最高等級的，即「經典的」。"}', 'classic novel / classic design / a classic example', '[{"en":"This is a classic example of Art Deco architecture.","zh-TW":"這是裝飾藝術建築的經典範例。"},{"en":"She loves reading classic literature.","zh-TW":"她喜歡閱讀經典文學。"}]', '{"noun":"classic","adjective":"classical"}', NULL, 3, 1134, NULL),
(1135, 'classify', '/ˈklæsɪfaɪ/', 'verb', '{"zh-TW":["分類；歸類"],"en":["to arrange in categories or groups"]}', '{"root":{"text":"class","meaning":"class/group (類別)"},"suffix":{"text":"-ify","meaning":"to make (使)"},"logic":"使成為類別，即「分類」。"}', 'classify information/data/documents', '[{"en":"Products are classified by type and price range.","zh-TW":"產品按類型和價格範圍分類。"},{"en":"The documents were classified as confidential.","zh-TW":"文件被歸類為機密。"}]', '{"noun":"classification"}', NULL, 3, 1135, 288),
(1136, 'classroom', '/ˈklæsruːm/', 'noun', '{"zh-TW":["教室"],"en":["a room where classes are taught"]}', NULL, 'in the classroom / classroom management', '[{"en":"The classroom was full of students.","zh-TW":"教室裡滿是學生。"},{"en":"Good classroom management is essential.","zh-TW":"良好的課堂管理很重要。"}]', NULL, NULL, 3, 1136, NULL),
(1137, 'classroom management', '/''klɑːsruːm ˌmænɪdʒmənt/', 'noun', '{"zh-TW":["班級管理；課堂管理"],"en":["the techniques used by teachers to maintain an orderly and productive learning environment"]}', NULL, 'effective classroom management / classroom management strategy / improve classroom management', '[{"en":"Good classroom management allows teachers to maximize instructional time.","zh-TW":"良好的班級管理使教師能夠最大化教學時間。"},{"en":"New teachers often struggle with classroom management in their early career.","zh-TW":"新教師在職業生涯初期通常會在班級管理上遇到困難。"}]', NULL, NULL, 5, 1137, NULL),
(1138, 'clause', '/klɔːz/', 'noun', '{"zh-TW":["條款；子句"],"en":["a particular section of a legal document","a section of a legal document"]}', '{"root":{"text":"claus","meaning":"close (關閉)"},"logic":"關閉（完結）一個段落，即「條款」。"}', 'contract clause / penalty clause / escape clause; escape clause / confidentiality clause', '[{"en":"The penalty clause specifies damages for late delivery.","zh-TW":"罰款條款規定了延遲交付的賠償金。"},{"en":"Review all clauses carefully before signing.","zh-TW":"簽名前請仔細審閱所有條款。"},{"en":"Read every clause before signing.","zh-TW":"簽名前請閱讀每一條款。"},{"en":"The contract includes a termination clause.","zh-TW":"合同包含終止條款。"}]', NULL, NULL, 2, 1138, NULL),
(1139, 'clawback', '/ˈklɔːbæk/', 'noun', '{"zh-TW":["追回款項；回收條款"],"en":["the action of recovering money previously paid out, especially bonuses or tax benefits"]}', NULL, 'trigger a clawback / clawback provision / executive clawback', '[{"en":"The clawback provision allowed the company to reclaim bonuses paid to executives who committed fraud.","zh-TW":"追回條款允許公司收回支付給犯有欺詐行為的高管的獎金。"},{"en":"A clawback clause protects investors if reported profits are later found to be inflated.","zh-TW":"如果後來發現報告的利潤虛高，追回條款可保護投資者。"}]', '{"verb":"claw back"}', NULL, 3, 1139, NULL),
(1140, 'clean', '/kliːn/', 'adjective', '{"zh-TW":["乾淨的；清潔","乾淨的"],"en":["free from dirt","to remove dirt"]}', NULL, 'clean energy / clean up; clean up / come clean', '[{"en":"We promote clean energy solutions.","zh-TW":"我們推廣潔淨能源方案。"},{"en":"Please clean up after the meeting.","zh-TW":"會議後請清理乾淨。"},{"en":"Keep your room clean.","zh-TW":"保持你的房間整潔。"},{"en":"He came clean about the mistake.","zh-TW":"他坦白了那個錯誤。"}]', '{"adjective":"clean","verb":"clean","noun":"cleaner","noun2":"cleanliness"}', NULL, 2, 1140, NULL),
(1141, 'clean energy', '/kliːn ˈɛnərdʒi/', 'noun', '{"zh-TW":["清潔能源"],"en":["energy from sources that do not pollute the environment"]}', NULL, 'invest in clean energy / clean energy transition', '[{"en":"Governments worldwide are investing in clean energy solutions.","zh-TW":"全球各國政府正在投資清潔能源解決方案。"},{"en":"Clean energy can reduce dependence on fossil fuels.","zh-TW":"清潔能源可以減少對化石燃料的依賴。"}]', NULL, NULL, 4, 1141, NULL),
(1142, 'clean technology', '/kliːn tekˈnɒlədʒi/', 'noun', '{"zh-TW":["清潔技術；環保技術"],"en":["technology that reduces negative environmental impacts"]}', NULL, 'invest in clean technology / clean technology innovation / clean technology company', '[{"en":"Governments subsidize clean technology to accelerate the energy transition.","zh-TW":"政府補貼清潔技術以加速能源轉型。"},{"en":"Clean technology businesses are attracting record levels of investment.","zh-TW":"清潔技術企業正在吸引創紀錄的投資水平。"}]', '{"adjective":"clean-tech"}', NULL, 5, 1142, NULL),
(1143, 'clean water', '/kliːn ˈwɔːtər/', 'noun', '{"zh-TW":["清潔飲水；乾淨水源"],"en":["water free from contamination suitable for drinking"]}', NULL, 'access to clean water / clean water initiative', '[{"en":"Access to clean water is a basic human right.","zh-TW":"獲得清潔飲水是基本人權。"},{"en":"The NGO works to provide clean water to rural communities.","zh-TW":"非政府組織致力於為農村社區提供清潔飲水。"}]', NULL, NULL, 4, 1143, NULL),
(1144, 'clear', '/klɪr/', 'adjective', '{"zh-TW":["清楚的；明確的"],"en":["easy to understand","transparent"]}', NULL, 'make clear / clear instructions', '[{"en":"The instructions are very clear.","zh-TW":"說明非常清楚。"},{"en":"Let me make one thing clear.","zh-TW":"讓我把一件事說清楚。"}]', '{"adjective":"clear","verb":"clear","adverb":"clearly","noun":"clarity"}', NULL, 2, 1144, NULL),
(1145, 'clearance', '/ˈklɪrəns/', 'noun', '{"zh-TW":["清倉；許可"],"en":["a sale to clear old stock","official permission"]}', '{"root":{"text":"clear","meaning":"clear (清除)"},"suffix":{"text":"-ance","meaning":"state of (狀態)"},"logic":"清除的狀態，指清倉或獲得許可。"}', 'clearance sale / security clearance', '[{"en":"The store is having a clearance sale this weekend.","zh-TW":"這家店本週末舉辦清倉特賣。"},{"en":"You need security clearance to enter.","zh-TW":"你需要安全許可才能進入。"}]', '{"verb":"clear","adjective":"clear"}', NULL, 3, 1145, NULL),
(1146, 'clearing house', '/ˈklɪərɪŋ haʊs/', 'noun', '{"zh-TW":["結算所；清算所"],"en":["an intermediary that facilitates the settlement of financial transactions"]}', NULL, 'use a clearing house / clearing house settlement', '[{"en":"All stock trades are settled through the national clearing house.","zh-TW":"所有股票交易都通過國家清算所進行結算。"},{"en":"A clearing house reduces counterparty risk in financial markets.","zh-TW":"結算所降低了金融市場中的交易對手風險。"}]', NULL, NULL, 5, 1146, NULL),
(1147, 'clearinghouse', '/ˈklɪərɪŋhaʊs/', 'noun', '{"zh-TW":["清算機構；結算所"],"en":["an institution that facilitates the exchange of payments between banks or traders"]}', NULL, 'settle through a clearinghouse / clearinghouse role', '[{"en":"All stock transactions are settled through the national clearinghouse.","zh-TW":"所有股票交易都通過國家清算機構結算。"},{"en":"The clearinghouse ensures counterparty risk is managed in derivatives trading.","zh-TW":"清算機構確保衍生品交易中的交易對手風險得到管理。"}]', NULL, NULL, 5, 1147, NULL),
(1148, 'clever', '/ˈklɛvər/', 'adjective', '{"zh-TW":["聰明的；機靈的"],"en":["quick at learning and understanding"]}', NULL, 'clever idea / too clever', '[{"en":"That''s a clever solution.","zh-TW":"那是個聰明的解決方案。"},{"en":"She''s a very clever girl.","zh-TW":"她是個非常聰明的女孩。"}]', '{"adverb":"cleverly","noun":"cleverness"}', NULL, 2, 1148, NULL),
(1149, 'click-through rate', '/klɪk θruː reɪt/', 'noun', '{"zh-TW":["點擊率"],"en":["the ratio of users who click on a link to the total number who saw it"]}', NULL, 'improve click-through rate / click-through rate benchmark / email click-through rate', '[{"en":"The new subject line doubled the email''s click-through rate.","zh-TW":"新的主旨行使電子郵件的點擊率翻倍。"},{"en":"A higher click-through rate indicates more engaging ad copy.","zh-TW":"更高的點擊率表示更吸引人的廣告文案。"}]', '{"abbreviation":"CTR"}', NULL, 5, 1149, NULL);